<?php
require __DIR__.'/bootstrap.php';$u=require_user();$uid=(int)$u['id'];
if(method()==='GET'){$stmt=$db->prepare("SELECT p.id,p.slug,p.title,p.price,p.sale_type,p.condition_label,pi.image_url image,a.current_price,a.ends_at FROM wishlist_items w JOIN products p ON p.id=w.product_id LEFT JOIN product_images pi ON pi.product_id=p.id AND pi.is_primary=1 LEFT JOIN auctions a ON a.product_id=p.id WHERE w.user_id=? ORDER BY w.created_at DESC");$stmt->bind_param('i',$uid);ok(db_all($stmt));}
$in=input();$pid=int_value($in['product_id']??($_GET['product_id']??null),'product');if(method()==='POST'){$stmt=$db->prepare('INSERT IGNORE INTO wishlist_items(user_id,product_id) VALUES(?,?)');$stmt->bind_param('ii',$uid,$pid);$stmt->execute();ok(null,'Saved to wishlist.',201);}if(method()==='DELETE'){$stmt=$db->prepare('DELETE FROM wishlist_items WHERE user_id=? AND product_id=?');$stmt->bind_param('ii',$uid,$pid);$stmt->execute();ok(null,'Removed from wishlist.');}fail('Method not allowed.',405);
